INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HVCSND', '7860100', 'Nghiệp vụ Cảnh sát - Vùng 1 - Nữ', NULL, 'bca', 30, 25.24, 2025, 'nu-vung-1', true, 'B', 'https://vietjack.com/diem-chuan-dai-hoc/diem-chuan-cac-truong-cong-an-nam-2025.jsp', '2025-08-23', 'Điểm xét tuyển khối Công an nhân dân đã quy về thang 30 theo công thức: Điểm xét tuyển = (điểm thi tốt nghiệp THPT theo tổ hợp quy về thang 30) x 2/5 + (điểm bài thi đánh giá của Bộ Công an thang 100 quy về thang 30) x 3/5, cộng điểm ưu tiên quy đổi. Bài thi Bộ Công an gốc thang 100. Điểm chuẩn tách theo giới tính và vùng tuyển sinh, không gộp chung.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
