INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HVQT', NULL, 'Các ngành (chưa công bố bảng riêng trong đợt đối chiếu)', NULL, 'bca', 30, NULL, 2025, 'chung', false, 'C', 'https://vietjack.com/diem-chuan-dai-hoc/diem-chuan-cac-truong-cong-an-nam-2025.jsp', '2025-08-23', 'Điểm xét tuyển khối Công an nhân dân đã quy về thang 30 theo công thức: Điểm xét tuyển = (điểm thi tốt nghiệp THPT theo tổ hợp quy về thang 30) x 2/5 + (điểm bài thi đánh giá của Bộ Công an thang 100 quy về thang 30) x 3/5, cộng điểm ưu tiên quy đổi. Bài thi Bộ Công an gốc thang 100. Điểm chuẩn tách theo giới tính và vùng tuyển sinh, không gộp chung. Học viện Quốc tế là trường thứ 8 khối Công an nhân dân nhưng chưa tìm thấy bảng điểm chuẩn riêng trong nguồn đã đối chiếu, để cutoff=null.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HVQT', '7220201', 'Ngôn ngữ Anh', ARRAY['A01','D01','D04','D09','D10']::text[], 'bca', 30, NULL, 2025, 'chung', false, 'C', 'https://fr.laodong.vn/tuyen-sinh/nganh-co-diem-chuan-cao-nhat-hoc-vien-quoc-te-bo-cong-an-1556201.ldo', '2025-08-12', 'Công thức BCA: THPT quy 30 ×2/5 + bài thi BCA quy 30 ×3/5. Năm 2025 Học viện Quốc tế tuyển 30 chỉ tiêu Ngôn ngữ Anh nhưng không tìm được bảng điểm trúng tuyển 2025 đã đối chiếu (nguồn Lao Động 12/8/2025 chỉ có dữ liệu 2024 trở về trước: khoảng 19,32–22,97). Để null, không bịa.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HVQT', '7220204', 'Ngôn ngữ Trung Quốc', ARRAY['A01','D01','D04','D09','D10']::text[], 'bca', 30, NULL, 2025, 'chung', false, 'C', 'https://fr.laodong.vn/tuyen-sinh/nganh-co-diem-chuan-cao-nhat-hoc-vien-quoc-te-bo-cong-an-1556201.ldo', '2025-08-12', 'Công thức BCA: THPT quy 30 ×2/5 + bài thi BCA quy 30 ×3/5. Năm 2025 tuyển 20 chỉ tiêu Ngôn ngữ Trung Quốc; chưa đối chiếu được điểm trúng tuyển 2025 chi tiết theo giới/bài thi CA. Để null.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HCMUT', NULL, 'Công nghệ Thông tin (Chương trình do Đại học Công nghệ Sydney cấp bằng)', NULL, 'combined', 100, 70.18, 2026, 'chung', true, 'B', 'http://danviet.vn/loat-truong-cong-bo-diem-chuan-xet-tuyen-dai-hoc-2026-tai-tphcm-uehuef-uit-d1450126.html', '2026-08-09', 'Điểm xét tuyển tổng hợp Trường Đại học Bách khoa TP.HCM thang 100 = Điểm học lực + Điểm cộng (tối đa 10) + Điểm ưu tiên. Điểm học lực kết hợp kết quả đánh giá năng lực V-ACT, điểm thi tốt nghiệp THPT và điểm học tập THPT theo công thức riêng cho từng đối tượng. Ngành tăng mạnh nhất năm 2026, từ 57,38 (2025) lên 70,18.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
