INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('DDS', '7140201', 'Giáo dục Mầm non', NULL, 'hsca', 30, 25.09, 2025, 'chung', true, 'C', 'https://trangedu.com/diem-chuan/diem-chuan-dai-hoc-su-pham-da-nang/', '2025-08-22', 'Trường Đại học Sư phạm - Đại học Đà Nẵng xét điểm kỳ thi đánh giá năng lực chuyên biệt của Trường Đại học Sư phạm TP.HCM (H-SCA), điểm công bố đã quy về thang 30. Điểm xét tuyển kết hợp H-SCA của Trường Đại học Sư phạm TP.HCM: điểm kỳ thi đánh giá năng lực chuyên biệt (thang 10/môn) kết hợp điểm học bạ THPT, quy về thang 30. Đây là điểm đã kết hợp, không phải điểm H-SCA thô và không so thô với điểm thi tốt nghiệp THPT.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
