INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HCMUE', '7140202', 'Giáo dục Tiểu học (Phân hiệu Gia Lai)', NULL, 'hsca', 30, 23.67, 2025, 'phan-hieu-gia-lai', true, 'B', 'https://baogialai.com.vn/phan-hieu-truong-dai-hoc-su-pham-tp-ho-chi-minh-tai-gia-lai-diem-chuan-trung-tuyen-tu-2202-2514-post564513.html', '2025-08-23', 'Điểm xét tuyển kết hợp H-SCA của Trường Đại học Sư phạm TP.HCM: điểm kỳ thi đánh giá năng lực chuyên biệt (thang 10/môn) kết hợp điểm học bạ THPT, quy về thang 30. Đây là điểm đã kết hợp, không phải điểm H-SCA thô và không so thô với điểm thi tốt nghiệp THPT. Số liệu Phân hiệu Gia Lai, phương thức kết hợp kết quả kỳ thi đánh giá năng lực chuyên biệt.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HCMUE', '7440112', 'Hoá học', ARRAY['A00 (môn chính Hóa học)']::text[], 'hsca', 30, 23.38, 2025, 'chung', true, 'B', 'https://Vietjack.com/diem-chuan-dai-hoc/dai-hoc-su-pham-tp-ho-chi-minh.jsp', '2025-08-23', 'Đã kết hợp học bạ + H-SCA theo công thức chung; tổ hợp gốc A00HO') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HCMUE', 'ALL', 'Khoảng điểm chung cơ sở chính (17,13-28,16 điểm)', NULL, 'hsca', 30, NULL, 2025, 'phan-hieu-gia-lai-va-nganh-tam-ly-hoc-da-doi-chieu-duoc', false, 'C', 'https://vnexpress.net/diem-san-dai-hoc-su-pham-tp-hcm-cao-nhat-24-5096240.html', '2026-07-11', 'Điểm xét tuyển kết hợp H-SCA của Trường Đại học Sư phạm TP.HCM: điểm kỳ thi đánh giá năng lực chuyên biệt (thang 10/môn) kết hợp điểm học bạ THPT, quy về thang 30. Đây là điểm đã kết hợp, không phải điểm H-SCA thô và không so thô với điểm thi tốt nghiệp THPT. VnExpress dẫn lại: năm 2025 điểm chuẩn phương thức kết hợp đánh giá năng lực chuyên biệt của trường rơi vào khoảng 17,13-28,16 điểm. Từ năm 2025 trường quy đổi các phương thức về thang chung khi lọc ảo nên bảng H-SCA riêng từng ngành không còn được công bố dạng text đầy đủ; các record ngành cụ thể năm 2025 trong bộ này chỉ gồm Phân hiệu Gia Lai và ngành Tâm lý học đã đối chiếu được.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
