INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HCMUE', '7310401', 'Tâm lý học', ARRAY['D01']::text[], 'hsca', 30, 28.08, 2025, 'chung', true, 'C', 'https://vinuni.edu.vn/vi/tam-ly-hoc-diem-chuan-bao-nhieu-nam-2024-tai-cac-truong-o-viet-nam/', '2025-08-22', 'Điểm xét tuyển kết hợp H-SCA của Trường Đại học Sư phạm TP.HCM: điểm kỳ thi đánh giá năng lực chuyên biệt (thang 10/môn) kết hợp điểm học bạ THPT, quy về thang 30. Đây là điểm đã kết hợp, không phải điểm H-SCA thô và không so thô với điểm thi tốt nghiệp THPT. Nguồn tổng hợp của VinUni nêu 28,08 là điểm kết hợp đánh giá năng lực chuyên biệt, phân biệt với 28,00 theo điểm thi tốt nghiệp THPT tổ hợp D01.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
