INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HUIT', NULL, 'Công nghệ Kỹ thuật Cơ Điện tử', NULL, 'hsca', 30, 23.81, 2026, 'chung', true, 'B', 'https://xaydungchinhsach.chinhphu.vn/diem-chuan-truong-dai-hoc-cong-thuong-tphcm-2026-119260810235737974.htm', '2026-08-09', 'Điểm xét tuyển kết hợp H-SCA của Trường Đại học Sư phạm TP.HCM: điểm kỳ thi đánh giá năng lực chuyên biệt (thang 10/môn) kết hợp điểm học bạ THPT, quy về thang 30. Đây là điểm đã kết hợp, không phải điểm H-SCA thô và không so thô với điểm thi tốt nghiệp THPT. Trường Đại học Công Thương TP.HCM dùng kết quả đánh giá năng lực chuyên biệt của Trường Đại học Sư phạm TP.HCM; điểm chuẩn toàn trường theo phương thức này năm 2026 từ khoảng 20 đến 24,44 điểm.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
