INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HUIT', 'ALL', 'Khoảng điểm chung toàn trường (20,25-26,25 điểm)', NULL, 'hsca', 30, NULL, 2025, 'chung', false, 'C', 'https://www.vietnam.vn/diem-chuan-truong-dh-cong-thuong-tp-hcm-tu-17-24-5-diem', '2025-08-22', 'Điểm xét tuyển kết hợp H-SCA của Trường Đại học Sư phạm TP.HCM: điểm kỳ thi đánh giá năng lực chuyên biệt (thang 10/môn) kết hợp điểm học bạ THPT, quy về thang 30. Đây là điểm đã kết hợp, không phải điểm H-SCA thô và không so thô với điểm thi tốt nghiệp THPT. Nguồn mới công bố khoảng điểm 20,25-26,25 cho phương thức đánh giá năng lực chuyên biệt tại Trường Đại học Công Thương TP.HCM năm 2025, chưa tách từng ngành trong phần đã đối chiếu nên để cutoff=null.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('UEH', 'ALL_MAX', 'Chương trình có điểm chuẩn cao nhất cơ sở TP.HCM (chưa rõ tên trong phần text)', NULL, 'combined', 100, 97, 2026, 'chung', true, 'B', 'http://danviet.vn/loat-truong-cong-bo-diem-chuan-xet-tuyen-dai-hoc-2026-tai-tphcm-uehuef-uit-d1450126.html', '2026-08-09', 'Xét tuyển tích hợp UEH năm 2026 thang 100 (năm đầu tiên áp dụng): quy đổi điểm từ các kỳ thi về một thang đo chung theo nguyên tắc tương đương của Bộ Giáo dục và Đào tạo; công thức dự kiến: Điểm xét tuyển = Điểm thi x hệ số a + Điểm trung bình các năm học THPT x hệ số b + Điểm cộng + Điểm ưu tiên, Toán nhân hệ số 2. Bảng chi tiết từng chương trình nằm trong ảnh thông báo của trường, phần text đã đối chiếu chỉ nêu khoảng điểm.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('UEH', 'ALL', 'Khoảng điểm chung 15 chương trình (60-67 điểm)', NULL, 'combined', 100, NULL, 2026, 'phan-hieu-vinh-long-dao-dong-60-67-diem', false, 'C', 'http://danviet.vn/loat-truong-cong-bo-diem-chuan-xet-tuyen-dai-hoc-2026-tai-tphcm-uehuef-uit-d1450126.html', '2026-08-09', 'Xét tuyển tích hợp UEH năm 2026 thang 100 (năm đầu tiên áp dụng): quy đổi điểm từ các kỳ thi về một thang đo chung theo nguyên tắc tương đương của Bộ Giáo dục và Đào tạo; công thức dự kiến: Điểm xét tuyển = Điểm thi x hệ số a + Điểm trung bình các năm học THPT x hệ số b + Điểm cộng + Điểm ưu tiên, Toán nhân hệ số 2. Bảng chi tiết từng chương trình nằm trong ảnh thông báo của trường, phần text đã đối chiếu chỉ nêu khoảng điểm. Phân hiệu Vĩnh Long dao động 60-67 điểm, chưa tách từng chương trình trong phần text đã đối chiếu nên để cutoff=null.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
