INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('UEH', 'ALL', 'Tất cả các chương trình - phương thức xét tuyển tích hợp thang 100 (mới từ 2026)', NULL, 'combined', 100, NULL, 2026, 'chung', false, 'A', 'https://www.ueh.edu.vn/bao-chi/dai-hoc-kinh-te-tp-hcm-chuyen-sang-xet-tuyen-ket-hop-nhan-doi-diem-toan-75786', '2026-02-25', 'UEH công bố từ năm 2026 dùng một phương thức xét tuyển kết hợp thang 100: Điểm xét tuyển = Điểm thi x hệ số a + Điểm trung bình các năm học THPT x hệ số b + Điểm cộng + Điểm ưu tiên, với Toán nhân hệ số 2 (riêng Tiếng Anh thương mại nhân hệ số 2 môn Tiếng Anh). Năm 2025 UEH vẫn công bố điểm chuẩn thang 30 theo 5 phương thức (22,8-27,7 tại cơ sở TP.HCM) chứ chưa dùng thang 100, nên không gán điểm 2025 vào INTEGRATED_100. Điểm chuẩn tích hợp 100 năm 2026 chưa có trong nguồn đã đối chiếu, để cutoff=null.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
