INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HMU', NULL, 'Các ngành xét kết quả SPT (chưa rõ ngành)', NULL, 'spt', 30, NULL, 2025, 'chung', false, 'C', 'https://www.vietnam.vn/de-tham-khao-12-mon-thi-danh-gia-nang-luc-dai-hoc-su-pham-ha-noi-2026', '2025-08-22', 'Điểm kỳ thi đánh giá năng lực SPT của Trường Đại học Sư phạm Hà Nội: mỗi môn thang 10, cộng theo tổ hợp 3 môn quy về thang 30. Không so trực tiếp với điểm thi tốt nghiệp THPT khi chưa qua bảng quy đổi tương đương của trường. Nguồn nêu Trường Đại học Y Dược Thái Bình và một số trường ngoài khối sư phạm dùng kết quả SPT năm 2025; chưa tìm thấy bảng điểm chuẩn SPT riêng của Trường Đại học Y Hà Nội nên để cutoff=null, cần bổ sung từ thông báo tuyển sinh của trường.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
