INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HNUE', '7140209', 'Sư phạm Toán học (tổ hợp Toán - Hóa)', NULL, 'spt', 30, NULL, 2026, 'chung', false, 'C', 'https://Vietjack.com/diem-chuan-dai-hoc/dai-hoc-su-pham-ha-noi.jsp', '2026-06-05', 'Điểm kỳ thi đánh giá năng lực SPT của Trường Đại học Sư phạm Hà Nội: mỗi môn thang 10, cộng theo tổ hợp 3 môn quy về thang 30. Không so trực tiếp với điểm thi tốt nghiệp THPT khi chưa qua bảng quy đổi tương đương của trường. Trích đoạn trên VietJack nêu 25 điểm theo trích đoạn cho đợt công bố điểm trúng tuyển SPT vào đầu tháng 6, nhưng chưa đối chiếu được bảng gốc đầy đủ của trường nên để cutoff=null. Từ năm 2025, HNUE gộp PT1/PT2/PT3 về một thang quy đổi tương đương chung nên điểm chuẩn tháng 8 không còn là điểm SPT thuần.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HNUE', '7140209', 'Sư phạm Toán học (tổ hợp Toán - Lý)', NULL, 'spt', 30, NULL, 2026, 'chung', false, 'C', 'https://Vietjack.com/diem-chuan-dai-hoc/dai-hoc-su-pham-ha-noi.jsp', '2026-06-05', 'Điểm kỳ thi đánh giá năng lực SPT của Trường Đại học Sư phạm Hà Nội: mỗi môn thang 10, cộng theo tổ hợp 3 môn quy về thang 30. Không so trực tiếp với điểm thi tốt nghiệp THPT khi chưa qua bảng quy đổi tương đương của trường. Trích đoạn trên VietJack nêu 25,28 điểm theo trích đoạn cho đợt công bố điểm trúng tuyển SPT vào đầu tháng 6, nhưng chưa đối chiếu được bảng gốc đầy đủ của trường nên để cutoff=null. Từ năm 2025, HNUE gộp PT1/PT2/PT3 về một thang quy đổi tương đương chung nên điểm chuẩn tháng 8 không còn là điểm SPT thuần.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
