INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('HPU2', '7420201', 'Công nghệ Sinh học', NULL, 'spt', 30, 20.5, 2024, 'chung', true, 'C', 'https://huongnghiepviet.com/tuyen-sinh/diem-chuan/diem-chuan-nam-2024-sp2-truong-dai-hoc-su-pham-ha-noi-2', '2024-08-17', 'Điểm kỳ thi đánh giá năng lực SPT của Trường Đại học Sư phạm Hà Nội: mỗi môn thang 10, cộng theo tổ hợp 3 môn quy về thang 30. Không so trực tiếp với điểm thi tốt nghiệp THPT khi chưa qua bảng quy đổi tương đương của trường. Trường Đại học Sư phạm Hà Nội 2 xét bằng kết quả SPT (cột PT402 trên bảng điểm của trường, khớp số liệu VietJack).') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
