INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('SGU', 'ALL', 'Tất cả các ngành xét V-SAT (đã quy đổi về thang 30 chung)', NULL, 'vsat', 450, NULL, 2025, 'chung', false, 'C', 'https://giadinh.edu.vn/nhieu-truong-dai-hoc-phia-nam-cong-bo-diem-trung-tuyen-nam-2025', '2025-08-22', 'Điểm V-SAT: mỗi môn thang 150, tổng tổ hợp 3 môn thang 450. Không so trực tiếp với thang 30 hay thang 1.200 của V-ACT khi chưa qua bảng quy đổi tương đương của trường. Năm 2025 trường quy đổi điểm V-SAT tương đương về thang 30 chung với điểm thi tốt nghiệp THPT (theo khung bách phân vị của Bộ Giáo dục và Đào tạo) và chỉ công bố một điểm chuẩn thang 30 duy nhất, không công bố điểm V-SAT thô theo ngành. Vì vậy cutoff V-SAT thô để null, không được lấy điểm thang 30 gán cho thang 450.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
