INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('UFM', NULL, 'Chương trình Tiếng Anh toàn phần (định hướng quốc tế) — mốc cao nhất của khoảng điểm V-SAT', NULL, 'vsat', 450, 453.48, 2025, 'chung', true, 'B', 'https://Vietjack.com/diem-chuan-dai-hoc/dai-hoc-tai-chinh-marketing.jsp', '2025-08-22', 'Số nguyên văn nguồn công bố, vượt 450 do đã gồm quy đổi/điểm cộng theo đề án UFM — giữ nguyên, không tự chuẩn hóa. [Cảnh báo: điểm chuẩn 453.48 vượt thang 450 — giữ nguyên số nguồn (đã gồm điểm cộng/quy đổi theo đề án của trường), không tự sửa.]') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
INSERT INTO public.admission_cutoffs (school_code, major_code, major_name, combo, method, scale, cutoff, year, segment, verified, reliability, source_url, source_date, note) VALUES ('UFM', NULL, 'Chương trình Tiếng Anh toàn phần (định hướng quốc tế) — mốc thấp nhất của khoảng điểm V-SAT', NULL, 'vsat', 450, 366.4, 2025, 'chung', true, 'B', 'https://Vietjack.com/diem-chuan-dai-hoc/dai-hoc-tai-chinh-marketing.jsp', '2025-08-22', 'Khoảng V-SAT chương trình Tiếng Anh toàn phần: 366,4–453,48.') ON CONFLICT ON CONSTRAINT admission_cutoffs_unique_point DO NOTHING;
