INSERT INTO public.admission_score_distributions (exam, year, session, scale, mean, median, sd, max_score, subject_stats, combos_mean, percentiles, source_url, source_date, reliability, note) VALUES ('hsa', 2026, 'chung', 150, 79.39, 79, 15, 133, NULL, NULL, '{"~5%": 105, "~10%": 100}'::jsonb, 'https://static-files.vnncdn.net/vps_documents/000001/000003/2026/5/29/fn-pho-diem-thi-va-phan-vi-hsa-2026-2503.pdf?s=YSlMjd4JJjUbmFWKFXfAzQ', '2026-05-29', 'A', 'Phổ điểm HSA 2026 (116.839 lượt thi có điểm sau sàng lọc; 121.010 đăng ký, 6 đợt 07/03–24/05/2026). Điểm cao nhất 133 thuộc mã bài thi HSA-F (phần 3 là Tiếng Anh). Số liệu trích từ phụ lục PDF của ĐHQGHN qua VietnamNet — file PDF không mở trực tiếp được trong phiên cào này, số liệu lấy từ bản trích dẫn trong kết quả tìm kiếm + bài Vietnam.vn 29/05/2026; cần tải lại PDF để lưu trữ lâu dài.') ON CONFLICT ON CONSTRAINT admission_score_distributions_unique_point DO NOTHING;
INSERT INTO public.admission_score_distributions (exam, year, session, scale, mean, median, sd, max_score, subject_stats, combos_mean, percentiles, source_url, source_date, reliability, note) VALUES ('hsa', 2024, 'chung', 150, 76.5, NULL, NULL, NULL, NULL, NULL, NULL, 'https://xaydungchinhsach.chinhphu.vn/print/pho-diem-ky-thi-danh-gia-nang-luc-hsa-nam-2025-cua-dai-hoc-quoc-gia-ha-noi-119250529223043086.htm', '2025-05-29', 'C', 'CHƯA VERIFY đầy đủ: chỉ có điểm trung bình 76,5 được nhắc lại khi so sánh với 2025 (78,8). Độ lệch chuẩn/trung vị/max/phân vị 2024 chưa trích được từ thông cáo gốc — để null.') ON CONFLICT ON CONSTRAINT admission_score_distributions_unique_point DO NOTHING;
INSERT INTO public.admission_score_distributions (exam, year, session, scale, mean, median, sd, max_score, subject_stats, combos_mean, percentiles, source_url, source_date, reliability, note) VALUES ('vact', 2025, 'chung', 1200, 662.78, 653, 159.7, 1122, NULL, NULL, '{"3%": 958, "5%": 932, "10%": 886, "20%": 815, "30%": 755, "40%": 701, "50%": 652, "60%": 605}'::jsonb, 'https://vnexpress.net/pho-diem-thi-danh-gia-nang-luc-nam-2025-cua-dai-hoc-quoc-gia-tp-hcm-4897966.html', '2025-06-12', 'A', 'Phổ điểm chung cả 2 đợt do ĐHQG-HCM công bố 12/06/2025. CẢNH BÁO: điểm trung bình đợt 2 (718,7) cao hơn đợt 1 (618,4) khoảng 100 điểm do khoảng 65.000 thí sinh thi lại có kinh nghiệm — không gộp thô 2 đợt khi ước tính. Mốc phân vị (tốp %) lấy từ bảng quy đổi phân vị của Trường Đại học Đồng Tháp áp dụng số liệu ĐHQG-HCM, kiểm chứng khớp trung vị 653.') ON CONFLICT ON CONSTRAINT admission_score_distributions_unique_point DO NOTHING;
INSERT INTO public.admission_score_distributions (exam, year, session, scale, mean, median, sd, max_score, subject_stats, combos_mean, percentiles, source_url, source_date, reliability, note) VALUES ('vact', 2026, 'chung', 1200, NULL, NULL, NULL, 1139, NULL, NULL, NULL, 'https://vietnamnet.vn/dh-quoc-gia-tphcm-cong-bo-diem-thi-danh-gia-nang-luc-dot-2-cho-170-000-thi-sinh-2522991.html', '2026-06-01', 'B', 'Đợt 2/2026 có hơn 170.000 thí sinh; thủ khoa 1.139 là kỷ lục của kỳ thi. Nhóm thi cả 2 đợt (khoảng 110.000 em) có trung bình đợt 2 là 713,7 — cao hơn hẳn trung bình chung 670,9: hiệu ứng thi lại lặp lại như 2025. Phổ điểm chung cả năm 2026 (mean/SD/trung vị gộp) CHƯA VERIFY trong đợt cào này — để null.') ON CONFLICT ON CONSTRAINT admission_score_distributions_unique_point DO NOTHING;
INSERT INTO public.admission_score_distributions (exam, year, session, scale, mean, median, sd, max_score, subject_stats, combos_mean, percentiles, source_url, source_date, reliability, note) VALUES ('vact', 2024, 'chung', 1200, NULL, NULL, NULL, 1116, NULL, NULL, NULL, 'https://tuoitre.vn/print/diem-chuan-danh-gia-nang-luc-truong-dai-hoc-kinh-te-luat-29-nganh-tren-800-20240702180120476.htm', '2024-07-02', 'C', 'CHƯA VERIFY phổ điểm 2024: chỉ verify được thủ khoa 1.116 điểm (thí sinh Trần Phạm Long Nghĩa, theo Tuổi Trẻ). Mean/SD/trung vị/phân vị 2024 cần lấy từ thông cáo gốc của ĐHQG-HCM — để null, không suy đoán.') ON CONFLICT ON CONSTRAINT admission_score_distributions_unique_point DO NOTHING;
INSERT INTO public.admission_score_distributions (exam, year, session, scale, mean, median, sd, max_score, subject_stats, combos_mean, percentiles, source_url, source_date, reliability, note) VALUES ('tsa', 2025, 'chung', 100, 55.23, NULL, NULL, 98.61, NULL, NULL, NULL, 'https://vnexpress.net/bach-khoa-ha-noi-ly-giai-cach-tinh-diem-thi-tsa-khi-thu-khoa-sai-9-cau-van-dat-diem-gan-tuyet-doi-5054552.html', '2026-03-25', 'B', 'Trung bình chung 55,23/100 của khoảng 28.700 thí sinh (gần 57.000 lượt thi, 3 đợt) do HUST công bố. TSA chấm bằng IRT: điểm thô (số câu đúng) không ánh xạ tuyến tính sang điểm TSA; thủ khoa 2025 đạt 98,61. Độ lệch chuẩn và bảng phân vị đầy đủ CHƯA VERIFY dạng text — để null.') ON CONFLICT ON CONSTRAINT admission_score_distributions_unique_point DO NOTHING;
